keyConcepts.codeExample:
class EmptyCartError(ValueError):
    """Levée quand le panier ne contient aucun article facturable."""

def calculate_discount(cart_total: float, loyalty_years: int) -> float:
    if cart_total <= 0:
        raise EmptyCartError("Le panier ne peut pas être vide ou négatif")
    rate = min(0.02 * loyalty_years, 0.20)
    return round(cart_total * rate, 2)

try:
    calculate_discount(0, loyalty_years=3)
except EmptyCartError as error:
    print(f"Remise refusée: {error}")

